from fastapi.applications import FastAPI
from typing import Dict, Any

# 1. Define test data
test_external_docs = {
    "description": "My external documentation link",
    "url": "http://example.com/docs"
}

# 2. Instantiate FastAPI with external_docs
try:
    app = FastAPI(external_docs=test_external_docs)
except Exception as e:
    print(f"Test failed during FastAPI instantiation: {e}")
    exit(1)

# 3. Generate OpenAPI schema
try:
    schema = app.openapi()
except Exception as e:
    print(f"Test failed during OpenAPI generation: {e}")
    exit(1)

# 4. Assert that external_docs is present in the schema root
if "external_docs" in schema and schema["external_docs"] == test_external_docs:
    print("SUCCESS: 'external_docs' parameter was correctly added to the OpenAPI schema root.")
else:
    print("FAILURE: 'external_docs' parameter was not found or was incorrect in the OpenAPI schema.")
    print(f"Schema keys: {list(schema.keys())}")
    if "external_docs" not in schema:
        print("Key 'external_docs' is missing.")
    else:
        print("Value mismatch.")

